class Fmt:
    @staticmethod
    def show(argv):
        return ' '.join(argv)

    @classmethod
    def label(cls, argv):
        return cls.__name__ + ': ' + ' '.join(argv)

print(Fmt.show(['pacman', '-Q', 'hyprland']))
print(Fmt.label(['sudo', 'pacman', '-S', '--noconfirm', 'foo']))
